import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { beforeAll, describe, expect, it } from 'vitest';
import { resample, SAMPLE_RATE } from '../src/voice/dsp';
import { assessQuality, extractUtterance, type Utterance } from '../src/voice/features';
import { buildProfile, matchUtterance, phraseSpread, type VoiceCommand, type VoiceProfile } from '../src/voice/matcher';
import { Segmenter } from '../src/voice/segmenter';

/**
 * End-to-end check of the voice matcher with speech generated by the voices
 * built into Windows (tests/make-fixtures.ps1). "Microsoft David" plays the
 * owner; Zira, Mark and Ravi play other people.
 */
const dir = join(__dirname, 'fixtures', 'audio');
const haveFixtures = existsSync(join(dir, 'david-wake-0.wav'));

function readWav(name: string): Float32Array {
  const buf = readFileSync(join(dir, name));
  let offset = 12;
  let rate = 16000;
  let channels = 1;
  let bits = 16;
  while (offset < buf.length - 8) {
    const id = buf.toString('ascii', offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    if (id === 'fmt ') {
      channels = buf.readUInt16LE(offset + 10);
      rate = buf.readUInt32LE(offset + 12);
      bits = buf.readUInt16LE(offset + 22);
    } else if (id === 'data') {
      if (bits !== 16) throw new Error(`unsupported bit depth ${bits}`);
      const frames = Math.floor(size / (2 * channels));
      const pcm = new Float32Array(frames);
      for (let i = 0; i < frames; i++) pcm[i] = buf.readInt16LE(offset + 8 + i * 2 * channels) / 32768;
      return resample(pcm, rate, SAMPLE_RATE);
    }
    offset += 8 + size + (size % 2);
  }
  throw new Error(`no data chunk in ${name}`);
}

/** Make synthetic speech less perfect: gain change, room noise and leading/trailing silence. */
function roughen(samples: Float32Array, seed: number, gain = 0.8): Float32Array {
  let s = seed;
  const rand = () => ((s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff) * 2 - 1;
  const pad = 4000;
  const out = new Float32Array(samples.length + pad * 2);
  for (let i = 0; i < out.length; i++) {
    const src = i - pad;
    out[i] = (src >= 0 && src < samples.length ? samples[src] * gain : 0) + rand() * 0.004;
  }
  return out;
}

const utter = (name: string, seed = 1, gain = 0.8): Utterance => extractUtterance(roughen(readWav(name), seed, gain));

function command(id: string, action: VoiceCommand['action'], files: string[]): VoiceCommand {
  const samples = files.map((f, i) => utter(f, i + 11, 0.7 + i * 0.1));
  return { id, phrase: id, action, samples, spread: phraseSpread(samples), createdAt: '' };
}

describe.skipIf(!haveFixtures)('voice matcher with generated speech', () => {
  let commands: VoiceCommand[];
  let profile: VoiceProfile;

  beforeAll(() => {
    commands = [
      command('wake', 'wake', ['david-wake-0.wav', 'david-wake-2.wav', 'david-wake-4.wav']),
      command('monitor', 'open-monitor', ['david-monitor-0.wav', 'david-monitor-2.wav', 'david-monitor-4.wav']),
    ];
    profile = buildProfile(commands.flatMap((c) => c.samples))!;
    expect(profile).not.toBeNull();
  });

  const run = (file: string) => {
    const r = matchUtterance(utter(file, 99), commands, profile);
    const d = r.detail;
    console.log(
      `${file.padEnd(22)} -> ${(r.command?.id ?? '—').padEnd(8)} phrase ${d.phraseRatio.toFixed(2)} timbre ${d.timbreRatio.toFixed(2)} pitch ${d.pitchSemitones.toFixed(1)}st`,
    );
    return r;
  };

  it('accepts the owner saying an enrolled phrase', () => {
    expect(run('david-wake-1.wav').command?.id).toBe('wake');
    expect(run('david-wake-3.wav').command?.id).toBe('wake');
    expect(run('david-monitor-1.wav').command?.id).toBe('monitor');
    expect(run('david-monitor-3.wav').command?.id).toBe('monitor');
  });

  it('ignores the owner saying something else', () => {
    expect(run('david-hello.wav').command).toBeNull();
    expect(run('david-weather.wav').command).toBeNull();
  });

  it('ignores a different voice saying the right phrase', () => {
    for (const f of ['zira-wake-0.wav', 'zira-wake-1.wav', 'zira-monitor-0.wav']) {
      const r = run(f);
      expect(r.command).toBeNull();
      expect(r.voiceOk).toBe(false);
    }
  });

  it('ignores other male voices saying the right phrase', () => {
    for (const f of ['mark-wake.wav', 'ravi-wake.wav', 'mark-monitor.wav', 'ravi-monitor.wav']) {
      if (!existsSync(join(dir, f))) continue;
      expect(run(f).command).toBeNull();
    }
  });

  it('records and recognises the owner in a noisy room, and still ignores others', () => {
    // Continuous background noise (fan / room / boosted mic). Samples are recorded
    // in the same room they are later spoken in, as a user would.
    for (const noiseRms of [0.004, 0.012, 0.02]) {
      let seed = 5;
      const rand = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff) * 2 - 1;
      const inRoom = (file: string, gain: number): Float32Array[] => {
        const speech = readWav(file);
        const lead = 16000 * 2;
        const total = new Float32Array(lead + speech.length + 16000 * 2);
        for (let i = 0; i < total.length; i++) {
          const src = i - lead;
          total[i] = rand() * noiseRms * 1.73 + (src >= 0 && src < speech.length ? speech[src] * gain : 0);
        }
        const found: Float32Array[] = [];
        const seg = new Segmenter({ onUtterance: (u) => found.push(u) });
        for (let i = 0; i < total.length; i += 1024) seg.push(total.subarray(i, i + 1024));
        return found;
      };
      const samples = ['david-wake-0.wav', 'david-wake-2.wav', 'david-wake-4.wav'].map((f, i) => {
        const found = inRoom(f, 0.4 + i * 0.1);
        expect(found.length).toBe(1);
        return extractUtterance(found[0]);
      });
      const wake: VoiceCommand = { id: 'wake', phrase: 'wake', action: 'wake', samples, spread: phraseSpread(samples), createdAt: '' };
      const roomProfile = buildProfile(samples);
      const db = (20 * Math.log10(noiseRms)).toFixed(0);
      for (const [file, expected] of [
        ['david-wake-1.wav', 'wake'],
        ['david-wake-3.wav', 'wake'],
        ['zira-wake-0.wav', null],
        ['david-hello.wav', null],
      ] as const) {
        // A sentence with pauses can split into several segments; none may trigger.
        const results = inRoom(file, 0.5).map((seg) => matchUtterance(extractUtterance(seg), [wake], roomProfile));
        const r = results.find((x) => x.command) ?? results[0];
        if (expected) expect(results.length).toBe(1);
        console.log(`noise ${db} dBFS ${file.padEnd(18)} -> ${(r.command?.id ?? '—').padEnd(5)} phrase ${r.detail.phraseRatio.toFixed(2)} timbre ${r.detail.timbreRatio.toFixed(2)} pitch ${r.detail.pitchSemitones.toFixed(1)}`);
        expect(r.command?.id ?? null).toBe(expected);
      }
    }
  });

  it('rejects a near-miss phrase at the default tolerance', () => {
    expect(run('david-travis.wav').command).toBeNull();
  });
});

describe('audio quality checks', () => {
  it('flags silence and very short sounds', () => {
    expect(assessQuality(new Float32Array(16000)).issue).toBe('too-quiet');
    const blip = new Float32Array(3200).map((_, i) => 0.3 * Math.sin(i / 5));
    expect(assessQuality(blip).issue).toBe('too-short');
  });
  it('flags clipping', () => {
    const loud = new Float32Array(16000).map((_, i) => (Math.sin(i / 7) > 0 ? 1 : -1));
    expect(assessQuality(loud).issue).toBe('clipped');
  });
});
